function deepMerge(target, source) {
  if (target === null || typeof target !== 'object') target = {};
  if (source === null || typeof source !== 'object') source = {};

  const result = { ...target };

  for (const key in source) {
    if (key === '__proto__' || key === 'constructor' || key === 'prototype') {
      continue;
    }

    if (source[key] && typeof source[key] === 'object' && !Array.isArray(source[key])) {
      result[key] = deepMerge(result[key], source[key]);
    } else {
      result[key] = source[key];
    }
  }

  return result;
}

function splitFees(totalWei, sharesBps) {
  if (sharesBps.reduce((sum, bps) => sum + bps, 0) !== 10000) {
    throw new Error("Shares must sum to exactly 10000");
  }

  const payouts = [];
  let remainingWei = totalWei;
  let totalBps = 0;

  for (let i = 0; i < sharesBps.length; i++) {
    const bps = sharesBps[i];
    totalBps += bps;

    if (i === sharesBps.length - 1) {
      // Last recipient gets all remaining wei
      payouts.push(remainingWei);
    } else {
      // Calculate payout for this recipient
      const weiForThisRecipient = (totalWei * BigInt(bps)) / 10000n;
      payouts.push(weiForThisRecipient);
      remainingWei -= weiForThisRecipient;
    }
  }

  return payouts;
}

function parseUnits(amountStr, decimals) {
  if (typeof amountStr !== 'string' || !/^\d+(\.\d+)?$/.test(amountStr)) {
    throw new Error('Invalid amount string');
  }

  const [integerPart, fractionalPart = ''] = amountStr.split('.');

  if (fractionalPart.length > decimals) {
    throw new Error('Too many fractional digits');
  }

  const paddedFractional = fractionalPart.padEnd(decimals, '0');
  const fullString = integerPart + paddedFractional;

  return BigInt(fullString);
}

function formatUnits(amountBig, decimals) {
  if (typeof amountBig !== 'bigint') {
    throw new Error('Amount must be a BigInt');
  }

  const amountStr = amountBig.toString();
  const leadingZeros = '0'.repeat(Math.max(0, decimals - amountStr.length));
  const paddedStr = leadingZeros + amountStr;

  const integerPart = paddedStr.slice(0, -decimals) || '0';
  const fractionalPart = paddedStr.slice(-decimals);

  if (fractionalPart === '0'.repeat(decimals)) {
    return integerPart;
  }

  const trimmedFractional = fractionalPart.replace(/0+$/, '');
  return `${integerPart}.${trimmedFractional}`;
}

function checkTransferResult(returnData, didRevert) {
    if (didRevert) return false;
    if (!returnData || returnData === "0x") return true;

    // Check if returnData is a valid 32-byte word
    if (typeof returnData !== 'string' || !/^(0x)?[0-9a-fA-F]{64}$/.test(returnData)) {
        throw new Error("Invalid return data");
    }

    const bytes = returnData.startsWith('0x') ? returnData.slice(2) : returnData;
    const lastByte = bytes.slice(-2);

    if (lastByte === '00') return false;
    if (lastByte === '01') return true;

    throw new Error("Invalid return data");
}
